import fs from 'node:fs'
import path from 'node:path'
import type { Lang } from './site'

export type PageData = {
  slug: string
  title: string
  description: string
  mainClass: string
  /** behaviour scripts the original page loaded besides site.js */
  scripts: ('offer' | 'experience' | 'contact' | 'intro')[]
  /** target of the language switch in the header (same page in the other language, or the objective page for compatibility pages) */
  langHref: string
  /** <main> inner HTML as generated by the v4.10.2 build, with internal links rewritten to Next routes */
  html: string
}

const dir = path.join(process.cwd(), 'content')

export const allSlugs = (): string[] => JSON.parse(fs.readFileSync(path.join(dir, 'slugs.json'), 'utf8'))

export function getPage(lang: Lang, slug: string): PageData | null {
  const f = path.join(dir, lang, `${slug}.json`)
  return fs.existsSync(f) ? (JSON.parse(fs.readFileSync(f, 'utf8')) as PageData) : null
}
